(function(){'use strict';var state={results:null,history:[]};var elements={};

function init(){elements={input:document.getElementById('jwt-input'),decodeBtn:document.getElementById('decode-btn'),resetBtn:document.getElementById('reset-btn'),emptyState:document.getElementById('empty-state'),statusBadge:document.getElementById('status-badge'),resultArea:document.getElementById('result-area'),panels:document.getElementById('jwt-panels'),headerBody:document.getElementById('jwt-header-body'),payloadBody:document.getElementById('jwt-payload-body'),signatureBody:document.getElementById('jwt-signature-body'),exportSection:document.getElementById('export-section'),exportCopy:document.getElementById('export-copy'),exportTxt:document.getElementById('export-txt'),exportJson:document.getElementById('export-json'),exportPrint:document.getElementById('export-print'),comparisonSection:document.getElementById('comparison-section'),comparisonSelect:document.getElementById('comparison-select'),comparisonTable:document.getElementById('comparison-table'),statAlgorithm:document.getElementById('stat-algorithm'),statTokenSize:document.getElementById('stat-token-size'),statClaims:document.getElementById('stat-claims'),statTime:document.getElementById('stat-delta')};
elements.decodeBtn.addEventListener('click',decode);elements.resetBtn.addEventListener('click',reset);elements.input.addEventListener('input',function(){updateStatus(elements.input.value.trim().length>0?'ready':'',elements.input.value.trim().length>0?'Ready':'');});
if(elements.exportCopy)elements.exportCopy.addEventListener('click',exportCopy);if(elements.exportTxt)elements.exportTxt.addEventListener('click',exportTxt);if(elements.exportJson)elements.exportJson.addEventListener('click',exportJson);if(elements.exportPrint)elements.exportPrint.addEventListener('click',exportPrint);if(elements.comparisonSelect)elements.comparisonSelect.addEventListener('change',onComparisonChange);showEmptyState();}

function updateStatus(type,text){if(elements.statusBadge){elements.statusBadge.className='status-badge'+(type?' '+type:'');elements.statusBadge.textContent=text;}}

function showEmptyState(){if(elements.emptyState)elements.emptyState.style.display='flex';if(elements.resultArea)elements.resultArea.style.display='none';}

function showResults(){if(elements.emptyState)elements.emptyState.style.display='none';if(elements.resultArea){elements.resultArea.style.display='block';elements.resultArea.classList.add('show');}}

function decode(){var token=elements.input.value.trim();if(!token){showEmptyState();return;}
updateStatus('processing','Decoding...');
var t0=performance.now();
setTimeout(function(){try{var parts=token.split('.');if(parts.length!==3){showToast('Invalid JWT format. Expected 3 parts separated by dots.','error');updateStatus('error','Error');return;}
var headerStr=base64UrlDecode(parts[0]);var payloadStr=base64UrlDecode(parts[1]);var signatureRaw=parts[2];
var header=JSON.parse(headerStr);var payload=JSON.parse(payloadStr);
var t1=performance.now();
elements.panels.style.display='grid';
elements.headerBody.innerHTML=syntaxHighlight(JSON.stringify(header,null,2));
elements.payloadBody.innerHTML=syntaxHighlight(JSON.stringify(payload,null,2));
elements.signatureBody.textContent=signatureRaw+' ('+Math.round(signatureRaw.length*3/4)+' bytes)';
var algo=header.alg||'unknown';var claimsCount=Object.keys(payload).length;
var tokenSize=token.length;
var stats={algorithm:algo,algorithmFull:algo,tokenSize:tokenSize,claims:claimsCount,header:header,payload:payload,signature:signatureRaw,token:token.substring(0,60)+(token.length>60?'...':''),time:t1-t0};
state.results=stats;if(state.history.length>=5)state.history.shift();state.history.push(stats);
elements.statAlgorithm.textContent=algo;elements.statTokenSize.textContent=formatBytes(tokenSize);elements.statClaims.textContent=claimsCount;if(elements.statTime)elements.statTime.textContent=(t1-t0)<1?'<1ms':Math.round(t1-t0)+'ms';
var printTitle=document.querySelector('.print-report-title');var printDate=document.querySelector('.print-report-date');if(printTitle)printTitle.textContent='JWT Decoder Report';if(printDate)printDate.textContent='Generated on '+new Date().toLocaleString('en-US',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
showResults();updateStatus('done','Completed');
if(elements.exportSection)elements.exportSection.style.display='flex';
renderComparison();}catch(e){showToast('Error decoding token: '+e.message,'error');updateStatus('error','Error');}},100);}

function base64UrlDecode(str){var base64=str.replace(/-/g,'+').replace(/_/g,'/');while(base64.length%4)base64+='=';try{return decodeURIComponent(escape(atob(base64)));}catch(e){return atob(base64);}}

function syntaxHighlight(json){return json.replace(/("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(\.\d+)?([eE][+-]?\d+)?)/g,function(match){var cls='json-number';if(/^"/.test(match)){if(/:$/.test(match)){cls='json-key';match=match.replace(/:$/,'')+':';}else{cls='json-string';}}else if(/true|false/.test(match)){cls='json-boolean';}else if(/null/.test(match)){cls='json-null';}return'<span class="'+cls+'">'+match+'</span>';});}

function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;
var available=state.history.filter(function(item){return!state.results||item.token!==state.results.token;});
if(available.length===0||state.history.length<=1){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}
if(elements.comparisonSection)elements.comparisonSection.style.display='block';
var html='<option value="">Select previous...</option>';
available.forEach(function(item,i){var idx=state.history.indexOf(item);
html+='<option value="'+idx+'">'+item.algorithm+' - '+item.claims+' claims</option>';});
elements.comparisonSelect.innerHTML=html;}

function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);
if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}
var prev=state.history[idx];var curr=state.results;
var metrics=[{label:'Algorithm',curr:curr.algorithm,prev:prev.algorithm},{label:'Token Size',curr:formatBytes(curr.tokenSize),prev:formatBytes(prev.tokenSize)},{label:'Claims',curr:curr.claims,prev:prev.claims}];
var html='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';
metrics.forEach(function(m){var diff=typeof m.curr==='number'?m.curr-m.prev:0;
var arrow=diff>0?'<span class="comp-up">+'+diff+'</span>':diff<0?'<span class="comp-down">'+diff+'</span>':'<span class="comp-same">0</span>';
html+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});
html+='</tbody></table>';elements.comparisonTable.innerHTML=html;}

function exportCopy(){if(!state.results)return;var r=state.results;var text='JWT Decoder Report\n==================\n\nAlgorithm: '+r.algorithm+'\nToken Size: '+formatBytes(r.tokenSize)+'\nClaims: '+r.claims+'\n\n--- Header ---\n'+JSON.stringify(r.header,null,2)+'\n\n--- Payload ---\n'+JSON.stringify(r.payload,null,2)+'\n\n--- Signature ---\n'+r.signature+'\n';if(navigator.clipboard){navigator.clipboard.writeText(text.trim()).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(text.trim());}}

function exportTxt(){if(!state.results)return;var r=state.results;var text='JWT Decoder Report\n==================\n\nAlgorithm: '+r.algorithm+'\nToken Size: '+formatBytes(r.tokenSize)+'\nClaims: '+r.claims+'\nProcessing Time: '+(r.time<1?'<1ms':Math.round(r.time)+'ms')+'\n\n--- Header ---\n'+JSON.stringify(r.header,null,2)+'\n\n--- Payload ---\n'+JSON.stringify(r.payload,null,2)+'\n\n--- Signature ---\n'+r.signature+'\n';downloadFile('jwt-decoded.txt',text,'text/plain');showToast('Downloaded TXT report','success');}

function exportJson(){if(!state.results)return;var r=state.results;var json=JSON.stringify({algorithm:r.algorithm,tokenSize:r.tokenSize,numberOfClaims:r.claims,header:r.header,payload:r.payload,signature:r.signature,processingTimeMs:Math.round(r.time),timestamp:new Date().toISOString()},null,2);downloadFile('jwt-decoded.json',json,'application/json');showToast('Downloaded JSON report','success');}

function exportPrint(){window.print();}
function downloadFile(filename,content,mimeType){var blob=new Blob([content],{type:mimeType});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}
function reset(){elements.input.value='';elements.panels.style.display='none';elements.headerBody.innerHTML='';elements.payloadBody.innerHTML='';elements.signatureBody.textContent='';state.results=null;state.history=[];if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.comparisonSection)elements.comparisonSection.style.display='none';}
function formatBytes(bytes){if(!bytes)return'0 B';if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();
